import { useState } from "react";

export default function App() {
  const [count, setCount] = useState<number>(0);

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="bg-white rounded-xl shadow-md p-8 flex flex-col items-center gap-4">
        <h1 className="text-2xl font-semibold text-gray-800">Contador</h1>

        <div className="flex items-center gap-6">
          <button
            type="button"
            onClick={() => setCount((c) => c - 1)}
            className="w-10 h-10 rounded-full bg-blue-600 text-white text-xl hover:bg-blue-700 transition-colors"
          >
            -
          </button>
          <span className="text-3xl font-bold min-w-[3ch] text-center">
            {count}
          </span>
          <button
            type="button"
            onClick={() => setCount((c) => c + 1)}
            className="w-10 h-10 rounded-full bg-blue-600 text-white text-xl hover:bg-blue-700 transition-colors"
          >
            +
          </button>
        </div>

        <p className="text-gray-600">El doble es {count * 2}</p>

        {count > 5 && (
          <p className="text-green-600 font-medium">¡Más de 5!</p>
        )}
      </div>
    </div>
  );
}

