  fn add(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      cart = cart.map(i => i.id == p.id ? { id: i.id, name: i.name, price: i.price, qty: i.qty + 1 } : i)
    } else {
      cart = [...cart, { id: p.id, name: p.name, price: p.price, qty: 1 }]
    }
  }

  fn inc(id) {
    cart = cart.map(i => i.id == id ? { id: i.id, name: i.name, price: i.price, qty: i.qty + 1 } : i)
  }

  fn dec(id) {
    cart = cart
      .map(i => i.id == id ? { id: i.id, name: i.name, price: i.price, qty: i.qty - 1 } : i)
      .filter(i => i.qty > 0)
