import { useState } from "react";

type Product = {
  id: number;
  nombre: string;
  precio: number;
};

const PRODUCTS: Product[] = [
  { id: 1, nombre: "Auriculares Bluetooth", precio: 49.99 },
  { id: 2, nombre: "Teclado mecánico", precio: 89.5 },
  { id: 3, nombre: "Mouse inalámbrico", precio: 25.75 },
];

export default function App() {
  const [cart, setCart] = useState<Record<number, number>>({});

  const agregar = (id: number) => {
    setCart((prev) => ({ ...prev, [id]: (prev[id] ?? 0) + 1 }));
  };

  const cambiar = (id: number, delta: number) => {
    setCart((prev) => {
      const nueva = (prev[id] ?? 0) + delta;
      const { [id]: _omit, ...resto } = prev;
      return nueva > 0 ? { ...resto, [id]: nueva } : resto;
    });
  };

  const items = PRODUCTS.filter((p) => cart[p.id] > 0).map((p) => ({
    ...p,
    cantidad: cart[p.id],
  }));

  const total = items.reduce((acc, i) => acc + i.precio * i.cantidad, 0);

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="mx-auto grid max-w-4xl gap-6 md:grid-cols-2">
        <section className="rounded-xl bg-white p-5 shadow">
          <h2 className="mb-4 text-xl font-bold text-gray-800">Productos</h2>
          <ul className="space-y-3">
            {PRODUCTS.map((p) => (
              <li
                key={p.id}
                className="flex items-center justify-between rounded-lg border border-gray-200 p-3"
              >
                <div>
                  <p className="font-medium text-gray-800">{p.nombre}</p>
                  <p className="text-sm text-gray-500">${p.precio.toFixed(2)}</p>
                </div>
                <button
                  onClick={() => agregar(p.id)}
                  className="rounded-md bg-blue-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-blue-700"
                >
                  Agregar
                </button>
              </li>
            ))}
          </ul>
        </section>

        <section className="rounded-xl bg-white p-5 shadow">
          <h2 className="mb-4 text-xl font-bold text-gray-800">Carrito</h2>
          {items.length === 0 ? (
            <p className="text-gray-500">El carrito está vacío.</p>
          ) : (
            <ul className="space-y-3">
              {items.map((i) => (
                <li
                  key={i.id}
                  className="flex items-center justify-between rounded-lg border border-gray-200 p-3"
                >
                  <div>
                    <p className="font-medium text-gray-800">{i.nombre}</p>
                    <p className="text-sm text-gray-500">
                      ${i.precio.toFixed(2)} c/u · Subtotal: $
                      {(i.precio * i.cantidad).toFixed(2)}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => cambiar(i.id, -1)}
