                      className="h-8 w-8 rounded bg-gray-200 font-bold hover:bg-gray-300"
                      aria-label={`Quitar una unidad de ${i.nombre}`}
                    >
                      -
                    </button>
                    <span className="w-6 text-center">{i.cantidad}</span>
                    <button
                      onClick={() => add(i.id)}
                      className="h-8 w-8 rounded bg-gray-200 font-bold hover:bg-gray-300"
                      aria-label={`Agregar una unidad de ${i.nombre}`}
                    >
                      +
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
          <div className="mt-4 flex items-center justify-between border-t pt-4 text-lg font-bold text-gray-800">
            <span>Total</span>
