import { useState } from "react";

type TabId = "perfil" | "ajustes" | "ayuda";

const TABS: { id: TabId; label: string; content: string }[] = [
  {
    id: "perfil",
    label: "Perfil",
    content:
      "Acá podés ver y editar tu información personal: nombre, foto y datos de contacto.",
  },
  {
    id: "ajustes",
    label: "Ajustes",
    content:
      "Configurá las preferencias de la aplicación: notificaciones, idioma y privacidad.",
  },
  {
    id: "ayuda",
    label: "Ayuda",
    content:
      "¿Necesitás asistencia? Consultá las preguntas frecuentes o contactá a nuestro equipo de soporte.",
  },
];

export default function App() {
  const [active, setActive] = useState<TabId>("perfil");
  const current = TABS.find((t) => t.id === active)!;

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="w-full max-w-lg bg-white rounded-xl shadow-md p-6">
        <h1 className="text-2xl font-bold text-gray-800 mb-4">Mi cuenta</h1>

        <div
          role="tablist"
          aria-label="Secciones"
          className="flex gap-2 border-b border-gray-200"
        >
          {TABS.map((tab) => {
            const isActive = tab.id === active;
            return (
              <button
                key={tab.id}
                id={`tab-${tab.id}`}
                role="tab"
                type="button"
                aria-selected={isActive}
                aria-controls={`panel-${tab.id}`}
                onClick={() => setActive(tab.id)}
                className={
                  "px-4 py-2 text-sm font-medium rounded-t-lg border-b-2 -mb-px transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-400 " +
                  (isActive
                    ? "border-indigo-600 text-indigo-700 bg-indigo-50"
                    : "border-transparent text-gray-500 hover:text-gray-800 hover:bg-gray-50")
                }
              >
                {tab.label}
              </button>
            );
          })}
        </div>

        <div
          id={`panel-${current.id}`}
          role="tabpanel"
          aria-labelledby={`tab-${current.id}`}
          className="pt-5 text-gray-700 leading-relaxed"
        >
          {current.content}
        </div>
      </div>
    </div>
  );
}

