page Todos "/" {
  state todos: Todo[] = []
  state draft = ""
  computed pending = todos.filter(t => !t.done).length
  fn add() {
    if draft.trim() == "" {
      return
    }
    todos.push({ id: crypto.randomUUID(), title: draft, done: false })
    draft = ""
  }
  computed doneCount = todos.filter(t => t.done).length
